const std=@import("std");
const Node=struct{key:i64,left:i32,right:i32,npl:i32};
fn mergeNodes(a:*[14]Node,x0:i32,y0:i32)i32{if(x0<0)return y0;if(y0<0)return x0;var x=x0;var y=y0;if(a[@intCast(x)].key>a[@intCast(y)].key)std.mem.swap(i32,&x,&y);const rr=a[@intCast(x)].right;a[@intCast(x)].right=mergeNodes(a,rr,y);const l=a[@intCast(x)].left;if(l<0){a[@intCast(x)].left=a[@intCast(x)].right;a[@intCast(x)].right= -1;}else{const r=a[@intCast(x)].right;if(a[@intCast(l)].npl<a[@intCast(r)].npl){const t=a[@intCast(x)].left;a[@intCast(x)].left=a[@intCast(x)].right;a[@intCast(x)].right=t;}const r2=a[@intCast(x)].right;a[@intCast(x)].npl=a[@intCast(r2)].npl+1;}return x;}
export fn leftist_heap(v:[*]const i64,n:usize)callconv(.c)f64{if(n<1 or n>43)return -1e300;const m=v[0];if(m<0 or m>14 or n!=@as(usize,@intCast(1+3*m)))return -1e300;var a=[_]Node{.{.key=0,.left=-1,.right=-1,.npl=0}}**14;var roots=[_]i32{-1,-1};var used:usize=0;var ex=0;var result:i64=0;for(0..@intCast(m))|i|{const k=v[1+3*i];const h=v[2+3*i];const z=v[3+3*i];if(k<0 or k>3)return -1e300;if(k==0){if(h<0 or h>1 or z<0 or z>9)return -1e300;const hi:usize=@intCast(h);a[used]=.{.key=z,.left=-1,.right=-1,.npl=0};roots[hi]=mergeNodes(&a,@intCast(used),roots[hi]);used+=1;}else if(k==1){if(h<0 or h>1 or z!=0)return -1e300;ex+=1;if(ex>10)return -1e300;const hi:usize=@intCast(h);const r=roots[hi];var got:i64= -1;if(r>=0){got=a[@intCast(r)].key;const l=a[@intCast(r)].left;const rr=a[@intCast(r)].right;roots[hi]=mergeNodes(&a,l,rr);}result=result*13+got+2;}else if(k==2){if(h!=0 or z!=0)return -1e300;roots[0]=mergeNodes(&a,roots[0],roots[1]);roots[1]= -1;}else{if(h<0 or h>1 or z!=0)return -1e300;roots[@intCast(h)]= -1;}}return @floatFromInt(result);}
